async def act(page):
    import re
    import asyncio

    # Navigate to the Reviews management page using a relative URL (idempotent)
    await page.goto('/index.php/admin/review/product/')
    await page.wait_for_load_state('networkidle')
    # small pause to let dynamic widgets render
    await asyncio.sleep(1)

    fragments = []

    # Collect visible text from tables
    tables = page.get_by_role('table')
    try:
        tcount = await tables.count()
    except Exception:
        tcount = 0
    for i in range(tcount):
        try:
            txt = await tables.nth(i).inner_text()
            if txt:
                fragments.append(txt)
        except Exception:
            pass

    # Collect text from groups
    groups = page.get_by_role('group')
    try:
        gcount = await groups.count()
    except Exception:
        gcount = 0
    for i in range(gcount):
        try:
            gtxt = await groups.nth(i).inner_text()
            if gtxt:
                fragments.append(gtxt)
        except Exception:
            pass

    # Collect text from links
    links = page.get_by_role('link')
    try:
        lcount = await links.count()
    except Exception:
        lcount = 0
    for i in range(lcount):
        try:
            ltxt = await links.nth(i).inner_text()
            if ltxt:
                fragments.append(ltxt)
        except Exception:
            pass

    # Collect text from headings
    headings = page.get_by_role('heading')
    try:
        hcount = await headings.count()
    except Exception:
        hcount = 0
    for i in range(hcount):
        try:
            htxt = await headings.nth(i).inner_text()
            if htxt:
                fragments.append(htxt)
        except Exception:
            pass

    # Collect text from cells
    cells = page.get_by_role('cell')
    try:
        ccount = await cells.count()
    except Exception:
        ccount = 0
    for i in range(ccount):
        try:
            ctx = await cells.nth(i).inner_text()
            if ctx:
                fragments.append(ctx)
        except Exception:
            pass

    # Fallback to raw HTML if nothing was captured
    if not fragments:
        try:
            fragments.append(await page.content())
        except Exception:
            fragments.append("")

    search_space = "\n".join(fragments)

    # Patterns to capture common textual formats: "Not Approved (3)", "Not Approved: 3", etc.
    patterns = [
        r"Not\s+Approved\s*\(\s*(\d+)\s*\)",
        r"Not\s+Approved\s*[:\-]\s*(\d+)",
        r"Not\s+Approved[\W\s]{0,50}(\d+)",
        r"Not\s+Approved\s*\n\s*(\d+)",
    ]

    count = None
    for pat in patterns:
        m = re.search(pat, search_space, flags=re.IGNORECASE)
        if m:
            count = m.group(1)
            break

    # If still not found, find the phrase and look for the nearest number after it
    if count is None:
        idx = search_space.lower().find('not approved')
        if idx != -1:
            snippet = search_space[idx: idx + 300]
            m = re.search(r"(\d+)", snippet)
            if m:
                count = m.group(1)

    # Final fallback: if the phrase exists but no number nearby, treat as 0; otherwise 0
    if count is None:
        if 'not approved' in search_space.lower():
            count = '0'
        else:
            count = '0'

    # Print only the numeric result so the harness can capture it
    print(count)

